SELECT x.position_id, x.id, x.observed_at, x.source_received_at, x.created_at, x.price, x.source, x.source_event_id, x.delivery_status, x.outcome_reason, TIMESTAMPDIFF(MICROSECOND, x.prev_obs, x.observed_at)/1000000 AS gap_s FROM (SELECT p.id AS position_id, e.*, LAG(e.observed_at) OVER (PARTITION BY p.id ORDER BY e.observed_at, e.id) AS prev_obs FROM paper_position p JOIN market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN (CASE WHEN p.id=143 THEN '2026-10-11 22:40:15' ELSE p.closed_at - INTERVAL 35 SECOND END) AND p.closed_at + INTERVAL 2 SECOND WHERE p.id IN (182,172,162,158,143,137)) x ORDER BY x.position_id, x.observed_at, x.id LIMIT 300